import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog"
import { UsersRound } from 'lucide-react'
import './styles/AddNewPerson.scss'

const AddNewPerson = () => {
    const [open, setOpen] = useState(false)

    return (
        <button className="add-group" type="button" onClick={() => {setOpen(true)}}>+&nbsp; <UsersRound /></button>
        
    )
}

export default AddNewPerson
